def _detect_dosage_form(name: str) -> str:
    """Detect dosage form from product name."""
    nl = name.lower()
    if 'tablet' in nl or 'tab ' in nl or nl.endswith('tab'):
        return 'tablet'
    if 'capsule' in nl or 'cap ' in nl or nl.endswith('cap'):
        return 'capsule'
    if 'syrup' in nl:
        return 'syrup'
    if 'injection' in nl or ' inj' in nl or ' pfi' in nl or 'infusion' in nl:
        return 'injection'
    if 'cream' in nl:
        return 'cream'
    if 'ointment' in nl:
        return 'ointment'
    if 'drop' in nl:
        return 'drops'
    if 'inhaler' in nl or 'inhal' in nl or 'nebuli' in nl or 'metered dose' in nl:
        return 'inhaler'
    if 'suppository' in nl or 'suppositories' in nl:
        return 'suppository'
    if 'suspension' in nl:
        return 'suspension'
    if 'powder' in nl:
        return 'powder'
    if 'gel' in nl:
        return 'gel'
    if 'patch' in nl:
        return 'patch'
    if 'lozenge' in nl:
        return 'lozenge'
    if 'spray' in nl:
        return 'spray'
    if 'solution' in nl or 'oral liquid' in nl:
        return 'solution'
    if 'pessary' in nl or 'pessaries' in nl:
        return 'suppository'
    if 'emulsion' in nl or 'lotion' in nl:
        return 'solution'
    if 'implant' in nl:
        return 'other'
    if 'vial' in nl or 'ampoule' in nl or 'syringe' in nl:
        return 'injection'
    if 'vaccine' in nl or 'serum' in nl or 'antiserum' in nl:
        return 'injection'
    return 'other'


def _extract_strength(name: str) -> str:
    """Extract strength/concentration from product name."""
    patterns = [
        r'(\d+(?:\.\d+)?(?:mg|mcg|g|iu|units?|mu)/\d+(?:\.\d+)?(?:ml|l|dose))',
        r'(\d+(?:\.\d+)?(?:mg|mcg|g|iu|mu|units?)(?:/(?:ml|l|dose))?)',
        r'(\d+(?:\.\d+)?%)',
    ]
    for pat in patterns:
        m = re.search(pat, name, re.IGNORECASE)
        if m:
            return m.group(1)
    return ''


def _get_category(code: str) -> str:
    """Get medication category from KEMSA product code."""
    # Check overrides first (more specific matches)
    for prefix, cat in CODE_CATEGORY_OVERRIDES.items():
        if code.startswith(prefix):
            return cat
    # Try 4-char prefix (PM01, PM02, etc.)
    cat = CODE_CATEGORY.get(code[:4])
    if cat:
        return cat
    # Try 2-char prefix (PV, PD, NM, etc.)
    return CODE_CATEGORY.get(code[:2], 'other')


def _get_controlled_class(code: str) -> str:
    """Get controlled substance schedule from product code."""
    for prefix, schedule in CONTROLLED_SUBSTANCES.items():
        if code.startswith(prefix):
            return schedule
    return ''


def _get_brand_names(name: str) -> list[str]:
    """Look up known brand names for a generic product."""
    nl = name.lower()
    for key, brands in BRAND_NAMES.items():
        if key in nl:
            return brands
    return []


class Command(BaseCommand):
    help = "Seed medication catalog from KEMSA product list (1000+ items)"

    def add_arguments(self, parser):
        parser.add_argument(
            "--reset",
            action="store_true",
            help="Delete all existing medications before seeding.",
        )
        parser.add_argument(
            "--skip-existing",
            action="store_true",
            help="Skip items that already exist (matched on product_code).",
        )

    @transaction.atomic
    def handle(self, *args, **opts):
        reset = opts["reset"]
        skip_existing = opts["skip_existing"]

        if reset:
            removed = Medication.objects.all().delete()[0]
            self.stdout.write(self.style.WARNING(f"Deleted {removed} existing medications."))

        # Build set of existing product codes for skip logic
        existing_codes: set[str] = set()
        if skip_existing or not reset:
            existing_codes = set(
                Medication.objects.values_list("product_code", flat=True)
            )

        to_create: list[Medication] = []
        seen: set[str] = set()
        skipped = 0

        for product_code, product_name, pack_size in STOCK_DATA:
            if product_code in seen:
                skipped += 1
                continue
            seen.add(product_code)

            if product_code in existing_codes:
                skipped += 1
                continue

            # Build generic_name as "product_name [pack_size]"
            if pack_size:
                generic_name = f"{product_name} [{pack_size}]"
            else:
                generic_name = product_name
            generic_name = generic_name[:255]  # Truncate to field max_length

            category = _get_category(product_code)
            dosage_form = _detect_dosage_form(product_name)
            strength = _extract_strength(product_name)
            controlled_class = _get_controlled_class(product_code)
            brand_names = _get_brand_names(product_name)
            side_effects = SIDE_EFFECTS.get(category, "")
            contraindications = CONTRAINDICATIONS.get(category, "")

            # Determine if prescription required
            requires_rx = category in (
                "oncology", "immunosuppressant", "cns", "cardiovascular",
                "hormone", "antibiotic", "antiviral", "antifungal",
                "vaccine",
            ) or bool(controlled_class)

            to_create.append(Medication(
                generic_name=generic_name,
                product_code=product_code,
                category=category if category in dict(Medication.Category.choices) else "other",
                dosage_form=dosage_form if dosage_form in dict(Medication.DosageForm.choices) else "other",
                strength=strength,
                brand_names=brand_names,
                requires_prescription=requires_rx,
                controlled_substance_class=controlled_class,
                side_effects=side_effects,
                contraindications=contraindications,
                description=f"KEMSA catalog item. Pack: {pack_size}" if pack_size else "KEMSA catalog item.",
                is_active=True,
            ))

        if to_create:
            Medication.objects.bulk_create(to_create, ignore_conflicts=True)

        self.stdout.write(self.style.SUCCESS(
            f"Done: {len(to_create)} created, {skipped} skipped."
        ))
